3936	    fn translate_entity_copy(
3937	        &mut self,
3938	        builder: &mut FunctionBuilder<'_>,
3939	        dst_entity: impl Into<CheckedEntity>,
3940	        src_entity: impl Into<CheckedEntity>,
3941	        dst: ir::Value,
3942	        src: ir::Value,
3943	        len: ir::Value,
3944	    ) -> WasmResult<()> {
3945	        let dst_entity = dst_entity.into();
3946	        let src_entity = src_entity.into();
3947	        let dst_idx_ty = dst_entity.index_type(self);
3948	        let src_idx_ty = src_entity.index_type(self);
3949	
3950	        // The length is 32-bit if either is 32-bit, but if they're both 64-bit
3951	        // then it's 64-bit.
3952	        let len_idx_ty = match (src_idx_ty, dst_idx_ty) {
3953	            (IndexType::I32, _) | (_, IndexType::I32) => IndexType::I32,
3954	            (IndexType::I64, IndexType::I64) => IndexType::I64,
3955	        };
3956	        let src_len = if src_idx_ty == len_idx_ty {
3957	            len
3958	        } else {
3959	            assert_eq!(src_idx_ty, IndexType::I64);
3960	            builder.ins().uextend(I64, len)
3961	        };
3962	        let dst_len = if dst_idx_ty == len_idx_ty {
3963	            len
3964	        } else {
3965	            assert_eq!(dst_idx_ty, IndexType::I64);
3966	            builder.ins().uextend(I64, len)
3967	        };
3968	
3969	        // Perform a bounds check for the src/dst entities and compute the raw
3970	        // heap addresses at the same time.
3971	        let dst_raw_addr = self.translate_entity_bounds_check(builder, dst_entity, dst, dst_len)?;
3972	        let src_raw_addr = self.translate_entity_bounds_check(builder, src_entity, src, src_len)?;
3973	
3974	        // Fit the `len` value to `pointer_type`. Note that at this point it's
3975	        // guaranteed inbounds so there's no loss in precision.
3976	        let len_ptr =
3977	            self.unchecked_cast_wasm_addr_to_native_addr(&mut builder.cursor(), len, len_idx_ty);
3978	
3979	        match dst_entity {
3980	            // Memories are always a `memcpy`.
3981	            CheckedEntity::Memory(_) => {
3982	                assert!(matches!(
3983	                    src_entity,
3984	                    CheckedEntity::Memory(_) | CheckedEntity::Data { .. }
3985	                ));
3986	                self.raw_bulk_memory_operation(
3987	                    builder,
3988	                    BulkOp::MemoryCopy {
3989	                        dst: dst_raw_addr,
3990	                        src: src_raw_addr,
3991	                        len: len_ptr,
3992	                    },
3993	                );
3994	                Ok(())
3995	            }
3996	
3997	            // Tables/arrays are sometimes a memcpy, sometimes a per-element
3998	            // loop. Delegate further to figure that out.
3999	            CheckedEntity::Table(_) | CheckedEntity::Array { .. } => self
4000	                .emit_raw_array_or_table_copy(
4001	                    builder,
4002	                    dst_entity,
4003	                    src_entity,
4004	                    dst_raw_addr,
4005	                    src_raw_addr,
4006	                    len_ptr,
4007	                    src,
4008	                ),
4009	
4010	            // Cannot copy into a data or element segment in wasm.
4011	            CheckedEntity::Data { .. } | CheckedEntity::Elem(_) => unreachable!(),
4012	        }
4013	    }
